def account_run(start, actions):
    class Account:
        def __init__(self, balance):
            self.balance = balance
            self.refused = 0

        def deposit(self, n):
            self.balance += n

        def withdraw(self, n):
            if n > self.balance:
                self.refused += 1
            else:
                self.balance -= n

    a = Account(start)
    for kind, n in actions:
        if kind == 'deposit':
            a.deposit(n)
        else:
            a.withdraw(n)
    return [a.balance, a.refused]

def stack_run(ops):
    class Stack:
        def __init__(self):
            self.items = []

        def push(self, x):
            self.items.append(x)

        def pop(self):
            if not self.items:
                return None
            return self.items.pop()

    s = Stack()
    out = []
    for op in ops:
        if op[0] == 'push':
            s.push(op[1])
        else:
            out.append(s.pop())
    return out

def speak_all(kinds):
    class Animal:
        def speak(self):
            return 'sound'

    class Dog(Animal):
        def speak(self):
            return 'woof'

    out = []
    for k in kinds:
        obj = Dog() if k == 'dog' else Animal()
        out.append(obj.speak())
    return out

